const K1C = { ink: '#2B2550', grid: '#E3DEF2', ax: '#2B2550', p: '#E5487A', b: '#2F7BC0', g: '#1B8862', o: '#EC7F1E', v: '#7C5CE0', fade: '#B7AED3' };
