  for (let y = yr[0]; y <= yr[1] + 1e-9; y += ys) s += `<path d="M${a4n(X(xr[0]))} ${a4n(Y(y))} H${a4n(X(xr[1]))}" stroke="${K1C.grid}" stroke-width="1"/>`;
