    for (let y = yr[0]; y <= yr[1] + 1e-9; y += ys) if (on(y, yl) && (q1 ? y > yr[0] + 1e-9 || true : Math.abs(y) > 1e-9)) s += k1T(X(ax0) - 6, Y(y) + 4, k1N(y), K1C.ink, 'k1n', 'end');
