const K1_Q = ['จตุภาคที่ 1', 'จตุภาคที่ 2', 'จตุภาคที่ 3', 'จตุภาคที่ 4'], k1Quad = (x, y) => x > 0 ? (y > 0 ? 0 : 3) : (y > 0 ? 1 : 2);
